class Solution {
public:
    int matrixSum(vector<vector<int>>& nums) {
        int m = nums.size();
        int n = nums[0].size();
        int count[1001];
        for (int i = 0; i < m; i++) {
            for (int v = 0; v <= 1000; v++) count[v] = 0;
            for (int x : nums[i]) count[x]++;
            int idx = 0;
            for (int v = 1000; v >= 0; v--) {
                while (count[v] > 0) {
                    nums[i][idx++] = v;
                    count[v]--;
                }
            }
        }
        int ans = 0;
        for (int j = 0; j < n; j++) {
            int mx = 0;
            for (int i = 0; i < m; i++) {
                if (nums[i][j] > mx) mx = nums[i][j];
            }
            ans += mx;
        }
        return ans;
    }
};
